import random
import itertools

def is_colorable(edges, k):
    adj = [[] for _ in range(14)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    color = [-1] * 14
    def bt(v):
        if v == 14:
            return True
        used = set(color[nei] for nei in adj[v] if color[nei] != -1)
        for c in range(k):
            if c not in used:
                color[v] = c
                if bt(v + 1):
                    return True
                color[v] = -1
        return False
    return bt(0)

found = False
random.seed(42)  # for reproducibility
possible_edges = list(itertools.combinations(range(14), 2))

for trial in range(10000):
    num_e = random.randint(28, 37)
    selected = random.sample(possible_edges, num_e)
    degrees = [0] * 14
    for u, v in selected:
        degrees[u] += 1
        degrees[v] += 1
    if min(degrees) < 4 or max(degrees) > 6:
        continue
    # check not 2-colorable
    if is_colorable(selected, 2):
        continue
    # check 4-colorable
    if is_colorable(selected, 4):
        print("Found graph with", len(selected), "edges")
        print(sorted(selected))
        found = True
        break

print("Found:", found)
print("Trials done:", trial + 1)
